from typing import List

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        INF = float('inf')
        # dp[a][b]: min sum using a op1 and b op2
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0
        for x in nums:
            # candidates: (cost1, cost2, value)
            cands = [(0, 0, x), (1, 0, (x + 1) // 2)]
            if x >= k:
                cands.append((0, 1, x - k))
                cands.append((1, 1, (x - k + 1) // 2))
            h = (x + 1) // 2
            if h >= k:
                cands.append((1, 1, h - k))
            ndp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
            for a in range(op1 + 1):
                for b in range(op2 + 1):
                    cur = dp[a][b]
                    if cur == INF:
                        continue
                    for c1, c2, v in cands:
                        na, nb = a + c1, b + c2
                        if na <= op1 and nb <= op2:
                            if cur + v < ndp[na][nb]:
                                ndp[na][nb] = cur + v
            dp = ndp
        return int(min(min(row) for row in dp))
from typing import List

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        INF = float('inf')
        n = len(nums)
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0
        for x in nums:
            # options: (value, cost1, cost2)
            opts = [(x, 0, 0)]
            h = (x + 1) // 2
            opts.append((h, 1, 0))
            if x >= k:
                opts.append((x - k, 0, 1))
                # op2 then op1
                opts.append(((x - k + 1) // 2, 1, 1))
            if h >= k:
                # op1 then op2
                opts.append((h - k, 1, 1))
            # keep only best for each (cost1, cost2) pair
            best = {}
            for v, c1, c2 in opts:
                key = (c1, c2)
                if key not in best or v < best[key]:
                    best[key] = v
            new = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
            for a in range(op1 + 1):
                row = dp[a]
                for b in range(op2 + 1):
                    cur = row[b]
                    if cur == INF:
                        continue
                    for (c1, c2), v in best.items():
                        na = a + c1
                        nb = b + c2
                        if na <= op1 and nb <= op2:
                            t = cur + v
                            if t < new[na][nb]:
                                new[na][nb] = t
            dp = new
        return int(min(min(row) for row in dp))

