    vals = [json.loads(line) for line in lines if line.strip() != ""]
    return vals[0], vals[1], vals[2], vals[3]

def validate(inp):
    try:
        lines = [l for l in inp.split("\n") if l.strip() != ""]
        if len(lines) != 4:
            return False
        nums = json.loads(lines[0])
        k = json.loads(lines[1])
        op1 = json.loads(lines[2])
        op2 = json.loads(lines[3])
    except Exception:
        return False
    if not isinstance(nums, list) or not all(isinstance(x, int) and not isinstance(x, bool) for x in nums):
        return False
    n = len(nums)
    if not (1 <= n <= 100):
        return False
    if not all(0 <= x <= 10**5 for x in nums):
        return False
    if not (isinstance(k, int) and 0 <= k <= 10**5):
        return False
    if not (isinstance(op1, int) and 0 <= op1 <= n):
        return False
    if not (isinstance(op2, int) and 0 <= op2 <= n):
        return False
    return True

def ref(inp):
    nums, k, op1, op2 = _parse(inp)
    n = len(nums)

    # Each element's possible outcomes: (value, ops1_used, ops2_used)
    def outcomes(x):
        res = [(x, 0, 0)]
        # only op1
        res.append(((x + 1) // 2, 1, 0))
        # only op2
        if x >= k:
            res.append((x - k, 0, 1))
        # both: op2 first then op1
        if x >= k:
            res.append((((x - k) + 1) // 2, 1, 1))
        # both: op1 first then op2
        y = (x + 1) // 2
        if y >= k:
            res.append((y - k, 1, 1))
        return res

    opts = [outcomes(x) for x in nums]

    @lru_cache(maxsize=None)
    def f(i, r1, r2):
        if i == n:
            return 0
        best = None
        for v, c1, c2 in opts[i]:
            if c1 <= r1 and c2 <= r2:
                rest = f(i + 1, r1 - c1, r2 - c2)
                cand = v + rest
                if best is None or cand < best:
                    best = cand
        return best

    return str(f(0, op1, op2))
