    op1 = int(lines[2])
    op2 = int(lines[3])
    n = len(nums)

    # All possible final values of one element, with (uses_op1, uses_op2).
    # Each op is applied at most once; order matters:
    #  - none
    #  - op2 only (needs x >= k)
    #  - op1 only
    #  - op1 then op2 (needs ceil(x/2) >= k)
    #  - op2 then op1 (needs x >= k)
    def outcomes(x):
        res = [(x, 0, 0)]
        if x >= k:
            res.append((x - k, 0, 1))
        h = (x + 1) // 2
        res.append((h, 1, 0))
        if h >= k:
            res.append((h - k, 1, 1))
        if x >= k:
            res.append(((x - k + 1) // 2, 1, 1))
        return res

    opts = [outcomes(x) for x in nums]

    def best(i, r1, r2):
        if i == n:
            return 0
        bestv = None
        for v, a, b in opts[i]:
            if a <= r1 and b <= r2:
                cand = v + best(i + 1, r1 - a, r2 - b)
                if bestv is None or cand < bestv:
                    bestv = cand
        return bestv

